from collections import defaultdict

def task_func(input_file="data.json"):
    """
    Reads a list of dictionaries from a JSON file, calculates the mean and median 
    for each numeric key, and returns a sorted Pandas DataFrame.

    Args:
        input_file (str): Path to the JSON file. Defaults to "data.json".

    Returns:
        pd.DataFrame: A DataFrame indexed and sorted by the variable names, 
                      containing columns 'mean' and 'median'.
    """
    try:
        with open(input_file, 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        # Return an empty DataFrame with the expected columns if file is missing or invalid
        return pd.DataFrame(columns=['mean', 'median'])

    # Dictionary to store numeric values for each key
    # Using defaultdict(list) to group values by their keys
    values_by_key = defaultdict(list)

    if isinstance(data, list):
        for entry in data:
            if isinstance(entry, dict):
                for key, value in entry.items():
                    # Check if value is numeric (int or float)
                    # Note: bool is a subclass of int in Python, so we exclude it explicitly.
                    # We also check for np.nan to ensure statistical validity.
                    if isinstance(value, (int, float)) and not isinstance(value, bool):
                        if not np.isnan(value):
                            values_by_key[key].append(value)

    # Calculate mean and median for each key that has numeric data
    results = {}
    for key, values in values_by_key.items():
        if values:
            results[key] = {
                'mean': float(np.mean(values)),
                'median': float(np.median(values))
            }

    # Convert the results dictionary to a DataFrame
    if not results:
        df = pd.DataFrame(columns=['mean', 'median'])
    else:
        # orient='index' uses the dictionary keys as the DataFrame index
        df = pd.DataFrame.from_dict(results, orient='index')
        # Sort the index (variable names) alphabetically
        df = df.sort_index()

    return df

